def avg(xs):
    return sum(xs) / len(xs)


def median(xs):
    ordered = sorted(xs)
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[mid]
    return avg(ordered[mid - 1:mid + 1])

